#!/usr/bin/env node
// Which code each critical edge function was deployed from. Lovable deploys
// edge functions separately from the website, so a merged fix can be live in
// the repo but not on the server. Each function below answers
// GET /functions/v1/<name>?__version with the fingerprint of its own source
// (index.ts plus every local file it imports), and this script compares that
// with the repo.
//
//   node scripts/function-versions.mjs           write _shared/functionVersions.generated.ts
//   node scripts/function-versions.mjs --check   fail if the generated file is out of date
//   node scripts/function-versions.mjs --live    compare the deployed functions with the repo
//
// The fingerprint is a hash of public source code; no data, secret or user
// information is involved.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join, relative, resolve } from 'node:path';

const ROOT = new URL('../', import.meta.url).pathname;
const FN = join(ROOT, 'supabase/functions');
const GENERATED = join(FN, '_shared/functionVersions.generated.ts');

/** Functions on the core flow and payments. Each calls versionProbe() first. */
export const VERSIONED = [
  'extract-document', 'verify-carbon', 'intelligence-chat', 'scope2-engine', 'scope3-trail',
  'delete-document', 'document-source-url', 'finance-application', 'esg-report-access',
  'create-razorpay-order', 'verify-razorpay-payment', 'razorpay-webhook',
];

const IMPORT = /(?:from\s+|import\s*\(?\s*)['"](\.{1,2}\/[^'"]+)['"]/g;

function sourceFiles(entry) {
  const seen = new Set();
  const walk = (file) => {
    if (seen.has(file) || file === GENERATED || !existsSync(file)) return;
    seen.add(file);
    for (const m of readFileSync(file, 'utf8').matchAll(IMPORT)) walk(resolve(dirname(file), m[1]));
  };
  walk(entry);
  return [...seen].sort();
}

export function fingerprint(name) {
  const h = createHash('sha256');
  for (const f of sourceFiles(join(FN, name, 'index.ts'))) h.update(relative(FN, f)).update('\0').update(readFileSync(f)).update('\0');
  return h.digest('hex').slice(0, 16);
}

export function generated() {
  const map = Object.fromEntries(VERSIONED.map((n) => [n, fingerprint(n)]));
  return `// Generated by scripts/function-versions.mjs. Do not edit.\n// Fingerprint of each function's own source, answered on GET ?__version.\nexport const FUNCTION_VERSIONS: Record<string, string> = ${JSON.stringify(map, null, 2)};\n`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const args = process.argv.slice(2);
  if (args.includes('--check')) {
    const ok = existsSync(GENERATED) && readFileSync(GENERATED, 'utf8') === generated();
    console.log(ok ? '✓ function versions up to date' : '✗ run: node scripts/function-versions.mjs');
    process.exit(ok ? 0 : 1);
  } else if (args.includes('--live')) {
    const env = Object.fromEntries(readFileSync(join(ROOT, '.env'), 'utf8').split('\n').map((l) => l.match(/^(\w+)="?([^"]*)"?$/)).filter(Boolean).map((m) => [m[1], m[2]]));
    const url = env.VITE_SUPABASE_URL, key = env.VITE_SUPABASE_PUBLISHABLE_KEY;
    let stale = 0;
    for (const name of VERSIONED) {
      const want = fingerprint(name);
      let got = 'no answer';
      try {
        const r = await fetch(`${url}/functions/v1/${name}?__version`, { headers: { apikey: key, Authorization: `Bearer ${key}` } });
        const j = r.ok ? await r.json().catch(() => null) : null;
        got = j?.version ?? `not reporting (HTTP ${r.status})`;
      } catch (e) { got = `unreachable (${e.message})`; }
      const match = got === want;
      if (!match) stale++;
      console.log(`${match ? '✓' : '✗'} ${name.padEnd(24)} repo ${want}  live ${got}`);
    }
    console.log(stale ? `\n${stale} function(s) differ from the repo: ask Lovable to redeploy them.` : '\nAll checked functions match the repo.');
  } else {
    writeFileSync(GENERATED, generated());
    console.log(`✓ wrote ${relative(ROOT, GENERATED)} (${VERSIONED.length} functions)`);
  }
}
